import React from 'react'
import {
    Board,
    CanvasItem,
    TextLabel,
    getReadableToneColor,
    getThemeColors,
    type ThemeMode,
} from 'vizmatic'

export const width = 860
export const height = 500
export const preset = 'engineering'
export const opaqueBackground = true

export const alt =
    'Speculative decoding pipeline showing five candidate tokens generated by a fast draft model. In a single parallel verification forward pass, the target model accepts the first four tokens, rejects the fifth, and emits a correction, producing five valid tokens in two compute units.'

export const numericAnchors = {
    draftTokens: ['graph', '.', 'allows', '(', 'user'],
    verifiedTokens: ['graph', '.', 'allows', '(', 'request'],
    acceptedCount: 4,
    rejectedIndex: 4,
    correction: 'request',
    emittedTotal: 5,
    draftCost: 1,
    verifyCost: 1,
    speedup: 2.5,
}

export function create(theme: ThemeMode = 'dark') {
    const c = getThemeColors(theme, theme === 'light' ? 'engineering' : 'default')
    const stroke = c.border
    const blueTone = getReadableToneColor('blue', c, c.bg)
    const greenTone = getReadableToneColor('green', c, c.bg)
    const redTone = getReadableToneColor('critical', c, c.bg)
    const purpleTone = getReadableToneColor('purple', c, c.bg)

    const label = (
        x: number,
        y: number,
        w: number,
        text: string,
        fontSize = 14,
        color = c.textPrimary,
        align: 'left' | 'center' | 'right' = 'left',
        weight = 500,
    ) => (
        <CanvasItem
            x={x}
            y={y}
            width={w}
            height={Math.min(
                height - y,
                Math.ceil(
                    fontSize *
                        1.4 *
                        Math.max(1, Math.ceil((text.length * fontSize * 0.55) / Math.max(w, 1))),
                ),
            )}
        >
            <TextLabel
                c={c}
                text={text}
                fontSize={fontSize}
                color={color}
                width="100%"
                align={align}
                fontWeight={weight}
            />
        </CanvasItem>
    )

    const draftTokens = ['graph', '.', 'allows', '(', 'user']
    const emittedTokens = ['graph', '.', 'allows', '(', 'request']

    return (
        <Board c={c} width={width} height={height} background="transparent">
            {/* SVG Background Boxes & Connectors */}
            <CanvasItem x={0} y={0} width={width} height={height}>
                <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
                    <defs>
                        <marker
                            id="spec-arr"
                            viewBox="0 0 10 10"
                            refX="6"
                            refY="5"
                            markerWidth="6"
                            markerHeight="6"
                            orient="auto-start-reverse"
                        >
                            <path d="M 0 1 L 8 5 L 0 9 z" fill={c.textMuted} />
                        </marker>
                    </defs>

                    {/* Draft token boxes */}
                    {draftTokens.map((_, i) => {
                        const bx = 40 + i * 156
                        const isReject = i === 4
                        const strokeColor = isReject ? redTone : blueTone
                        const fillColor = isReject
                            ? theme === 'dark'
                                ? '#3d1414'
                                : '#fee2e2'
                            : theme === 'dark'
                              ? '#112236'
                              : '#eff6ff'
                        return (
                            <g key={`box-d-${i}`}>
                                <rect
                                    x={bx}
                                    y={114}
                                    width={142}
                                    height={50}
                                    rx={8}
                                    fill={fillColor}
                                    stroke={strokeColor}
                                    strokeWidth={1.5}
                                />
                                {/* Arrow to verification */}
                                <line
                                    x1={bx + 71}
                                    y1={164}
                                    x2={bx + 71}
                                    y2={222}
                                    stroke={strokeColor}
                                    strokeWidth={1.5}
                                    markerEnd="url(#spec-arr)"
                                />
                            </g>
                        )
                    })}

                    {/* Verification boxes */}
                    {draftTokens.map((_, i) => {
                        const bx = 40 + i * 156
                        const isReject = i === 4
                        const strokeColor = isReject ? redTone : greenTone
                        const fillColor = isReject
                            ? theme === 'dark'
                                ? '#3d1414'
                                : '#fee2e2'
                            : theme === 'dark'
                              ? '#102e1c'
                              : '#f0fdf4'
                        return (
                            <g key={`box-v-${i}`}>
                                <rect
                                    x={bx}
                                    y={224}
                                    width={142}
                                    height={48}
                                    rx={8}
                                    fill={fillColor}
                                    stroke={strokeColor}
                                    strokeWidth={1.5}
                                />
                                {/* Arrow to emission */}
                                <line
                                    x1={bx + 71}
                                    y1={272}
                                    x2={bx + 71}
                                    y2={314}
                                    stroke={c.textMuted}
                                    strokeWidth={1.5}
                                    markerEnd="url(#spec-arr)"
                                />
                            </g>
                        )
                    })}

                    {/* Emitted boxes */}
                    {emittedTokens.map((_, i) => {
                        const bx = 40 + i * 156
                        const isCorrection = i === 4
                        const strokeColor = isCorrection ? purpleTone : greenTone
                        const fillColor = isCorrection
                            ? theme === 'dark'
                                ? '#2e183a'
                                : '#faf5ff'
                            : theme === 'dark'
                              ? '#102e1c'
                              : '#f0fdf4'
                        return (
                            <rect
                                key={`box-e-${i}`}
                                x={bx}
                                y={316}
                                width={142}
                                height={50}
                                rx={8}
                                fill={fillColor}
                                stroke={strokeColor}
                                strokeWidth={1.5}
                            />
                        )
                    })}

                    {/* Footer summary container */}
                    <rect
                        x={40}
                        y={394}
                        width={780}
                        height={64}
                        rx={8}
                        fill={theme === 'dark' ? '#151921' : '#f8fafc'}
                        stroke={stroke}
                        strokeWidth={1}
                    />
                    <line x1={294} y1={404} x2={294} y2={448} stroke={stroke} strokeWidth={1} />
                    <line x1={544} y1={404} x2={544} y2={448} stroke={stroke} strokeWidth={1} />
                </svg>
            </CanvasItem>

            {/* Header */}
            {label(
                40,
                24,
                780,
                'Speculative Decoding: Autoregressive Draft & Parallel Verification',
                20,
                c.textPrimary,
                'left',
                700,
            )}
            {label(
                40,
                52,
                780,
                'Small draft model samples gamma=5 candidate tokens; large target model evaluates all positions in one forward pass',
                13,
                c.textSecondary,
                'left',
                400,
            )}

            {/* Stage 1: Draft */}
            {label(
                40,
                92,
                780,
                'STAGE 1: FAST DRAFT MODEL GENERATION (GAMMA = 5 CANDIDATES)',
                12,
                blueTone,
                'left',
                700,
            )}

            {draftTokens.map((tok, i) => {
                const bx = 40 + i * 156
                const isReject = i === 4
                const tone = isReject ? redTone : blueTone
                return (
                    <React.Fragment key={`draft-${i}`}>
                        {label(bx, 118, 142, `Token #${i + 1}`, 11, c.textMuted, 'center', 500)}
                        {label(bx, 138, 142, tok, 17, tone, 'center', 700)}
                    </React.Fragment>
                )
            })}

            {/* Stage 2: Target verification */}
            {label(
                40,
                206,
                780,
                'STAGE 2: TARGET VERIFICATION (SINGLE PARALLEL FORWARD PASS)',
                12,
                greenTone,
                'left',
                700,
            )}

            {draftTokens.map((_, i) => {
                const bx = 40 + i * 156
                const isReject = i === 4
                const tone = isReject ? redTone : greenTone
                const status = isReject ? 'REJECT' : 'ACCEPT'
                const note = isReject ? 'Mismatch' : 'Matches target'
                return (
                    <React.Fragment key={`verif-${i}`}>
                        {label(bx, 230, 142, status, 13, tone, 'center', 700)}
                        {label(bx, 248, 142, note, 11, c.textSecondary, 'center', 400)}
                    </React.Fragment>
                )
            })}

            {/* Stage 3: Emitted tokens */}
            {label(
                40,
                298,
                780,
                'STAGE 3: FINAL EMITTED TOKENS (COMMITTED TO EDITOR)',
                12,
                purpleTone,
                'left',
                700,
            )}

            {emittedTokens.map((tok, i) => {
                const bx = 40 + i * 156
                const isCorrection = i === 4
                const tone = isCorrection ? purpleTone : greenTone
                const sub = isCorrection ? 'Correction' : 'Accepted'
                return (
                    <React.Fragment key={`emit-${i}`}>
                        {label(bx, 322, 142, tok, 17, tone, 'center', 700)}
                        {label(bx, 344, 142, sub, 11, c.textMuted, 'center', 500)}
                    </React.Fragment>
                )
            })}

            {/* Metrics footer */}
            {label(64, 404, 230, 'Compute Budget', 12, c.textMuted, 'center', 500)}
            {label(
                64,
                424,
                230,
                '1.0 (Draft) + 1.0 (Verify) = 2.0 Units',
                14,
                c.textPrimary,
                'center',
                700,
            )}

            {label(314, 404, 230, 'Tokens Emitted', 12, c.textMuted, 'center', 500)}
            {label(
                314,
                424,
                230,
                '5 tokens (4 accepted + 1 correction)',
                14,
                greenTone,
                'center',
                700,
            )}

            {label(564, 404, 230, 'Effective Throughput', 12, c.textMuted, 'center', 500)}
            {label(
                564,
                424,
                230,
                '2.50 tokens / compute unit (2.5x gain)',
                14,
                blueTone,
                'center',
                700,
            )}
        </Board>
    )
}

export default create()
